mapper.select:
SELECT id, task_id, menu_code, operator_employee_id, operator_name, subscriber_app, data_source_key, query_params, export_url, export_name, file_format, processed_rows, total_rows, progress, status, error_message, received_at, export_time, checkpoint_last_id, checkpoint_part_no, temp_file_path, retry_count, created_at, updated_at FROM export_data_task
AND operator_employee_id = #{query.employeeId}
AND menu_code = #{query.menuCode}
AND status = #{query.status}
AND subscriber_app = #{query.subscriberApp}
AND created_at >= #{query.startTime}
AND created_at <= #{query.endTime}
ORDER BY created_at DESC
